point = int(point)

if major == 2 and minor == 1:

if 'dev' in ver and not point:

if major > 2 or major == 2 and minor > 1:

msg = 'Using dev zmq module, please report unexpected results'

if point and point >= 9:

return True

log.critical('ZeroMQ python bindings >= 2.1.9 are required')

if is_console_configured():

return True

if 'salt-master' in sys.argv[0]:

log.warning(msg)

sys.stderr.write('WARNING: {0}\n'.format(msg))

msg = (
    'The Salt Master is unstable using a ZeroMQ version lower than 2.1.11 and requires this fix: http://lists.zeromq.org/pipermail/zeromq-dev/2011-June/012094.html'
