async def _prep_event(self, origin: str, event: EventBase, state: Optional[...

context = await self.state_handler.compute_event_context(event, old_state=state
    )

if not auth_events:

prev_state_ids = await context.get_prev_state_ids()

if event.type == EventTypes.Member and not event.auth_event_ids():

auth_events_ids = self.auth.compute_auth_events(event, prev_state_ids,
    for_verification=True)

if len(event.prev_event_ids()) == 1 and event.depth < 5:

context = await self.do_auth(origin, event, context, auth_events=auth_events)

auth_events_x = await self.store.get_events(auth_events_ids)

c = await self.store.get_event(event.prev_event_ids()[0], allow_none=True)

if not context.rejected:

auth_events = {(e.type, e.state_key): e for e in auth_events_x.values()}

if c and c.type == EventTypes.Create:

await self._check_for_soft_fail(event, state, backfilled)

if event.type == EventTypes.GuestAccess and not context.rejected:

auth_events[c.type, c.state_key] = c

await self.maybe_kick_guest_users(event)

return context

