def header(self, text, level, raw=None):...

"""docstring"""

return '<h%d>%s</h%d>\n' % (level, text, level)

def dataReceived(self, data):...

self._reader.feed(data)

while True:

msg = self._reader.gets()

if msg is False:

return

if not isinstance(msg, list):

self.handle_command(msg[0], *msg[1:])

__version__ = '2.6.0b0'

if __name__ == '__main__':

print(__version__)

def output_loose_item(self):...

body = self.renderer.placeholder()

while self.pop()['type'] != 'list_item_end':

body += self.tok()

return self.renderer.list_item(body)

def _handleText(self, text, expr):...

if text is self.getDefault() or text is None:

return text

if isinstance(text, str):

return text

if isinstance(text, bytes):

resolver = queryUtility(IUnicodeEncodingConflictResolver)

return str(text)

if resolver is None:

return text.decode('ascii')

return resolver.resolve(self.contexts.get('context'), text, expr)

LOG.error(
    """UnicodeDecodeError detected for expression "%s"
Resolver class: %s
Exception text: %s
Template: %s
Rendered text: %r"""
     % (expr, resolver.__class__, e, self.contexts['template'].absolute_url
    (1), text))

