logger.info(query)

return dict(error='Error executing query: %s' % query)

idx = 0

hits = t.getWhereList(query, None, 0, rows, 1)

batch = 1000

totalCount = len(hits)

while idx < len(h):

hits = hits[range_start:range_end]

batch = min(batch, len(h) - idx)

row_gen = row_generator(t, hits)

res = table.slice(col_indices, h[idx:idx + batch])

rsp_data = {'data': {'column_types': [col.__class__.__name__ for col in
    cols], 'columns': [col.name for col in cols]}, 'meta': {'rowCount':
    rows, 'totalCount': totalCount, 'limit': limit, 'offset': offset}}

idx += batch

