return False

if cipher.encryptionMethod().upper().startswith('RC4'):

return False

if cipher.encryptionMethod().upper().startswith('DES'):

return False

if 'MD5' in tokens:

return False

if cipher.authenticationMethod() in ['aNULL', 'NULL']:

return False

if cipher.encryptionMethod() in ['eNULL', 'NULL']:

return False

if 'EXP' in tokens or 'EXPORT' in tokens:

return False

if 'ADH' in tokens:

return False

return True

