def adv_search_custom_columns(cc, term, q):...

for c in cc:

if c.datatype == 'datetime':

return q

custom_start = term.get('custom_column_' + str(c.id) + '_start')

custom_query = term.get('custom_column_' + str(c.id))

custom_end = term.get('custom_column_' + str(c.id) + '_end')

if custom_query != '' and custom_query is not None:

if custom_start:

if c.datatype == 'bool':

q = q.filter(getattr(db.Books, 'custom_column_' + str(c.id)).any(func.
    datetime(db.cc_classes[c.id].value) >= func.datetime(custom_start)))

if custom_end:

q = q.filter(getattr(db.Books, 'custom_column_' + str(c.id)).any(db.
    cc_classes[c.id].value == (custom_query == 'True')))

if c.datatype == 'int' or c.datatype == 'float':

q = q.filter(getattr(db.Books, 'custom_column_' + str(c.id)).any(func.
    datetime(db.cc_classes[c.id].value) <= func.datetime(custom_end)))

q = q.filter(getattr(db.Books, 'custom_column_' + str(c.id)).any(db.
    cc_classes[c.id].value == custom_query))

if c.datatype == 'rating':

q = q.filter(getattr(db.Books, 'custom_column_' + str(c.id)).any(db.
    cc_classes[c.id].value == int(float(custom_query) * 2)))

q = q.filter(getattr(db.Books, 'custom_column_' + str(c.id)).any(func.lower
    (db.cc_classes[c.id].value).ilike('%' + custom_query + '%')))

